int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long red, green, blue;
    cin >> red >> green >> blue;

    long long mixed = min({red, green, blue});
    long long answer = 0;

    for (long long d = 0; d < 3 && d <= mixed; ++d) {
        long long x = mixed - d;
        answer = max(answer, x + (red - x) / 3
