#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long red, green, blue;
    cin >> red >> green >> blue;

    long long n = min({red, green, blue});

    if (n == 0) {
        cout << red / 3 + green / 3 + blue / 3;
        return 0;
    }

    long long count = n;
    red -= n;
    green -= n;
    blue -= n;

    count += red / 3 + green / 3 + blue / 3;

    if (red % 3 + green % 3 + blue % 3 == 4) {
        ++count;
    }

    cout << count;
    return 0;
}

