    long long red, green, blue;
    cin >> red >> green >> blue;

    long long mixed = min({red, green, blue});
    long long answer = 0;

    for (long long take = mixed; take >= max(0LL, mixed - 2); --take) {
        answer = max(answer, take
            + (red - take) / 3
            + (green - take) / 3
            + (blue - take) / 3);
    }

    cout << answer << '\n';
    return 0;
}

